(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3000);
  const box = (sel) => { const el = document.querySelector(sel); if (!el) return null; const b = el.getBoundingClientRect(); return { w: Math.round(b.width), h: Math.round(b.height), top: Math.round(b.top), ratio: +(b.width / b.height).toFixed(2) }; };
  return JSON.stringify({
    viewport: { w: innerWidth, h: innerHeight },
    main: box('.pj-main'),
    head: box('.pj-head'),
    gridMain: box('.pj-grid-main'),
    canvas: box('.pj-canvas'),
    infoCard: box('.pj-info'),
    gridBottom: box('.pj-grid-bottom'),
    bomCard: box('.pj-table-wrap'),
    steps: box('.pj-grid-steps'),
    docHeight: document.documentElement.scrollHeight,
    mainStyle: getComputedStyle(document.querySelector('.pj-main')).maxWidth,
    gridCols: getComputedStyle(document.querySelector('.pj-grid-main')).gridTemplateColumns,
    bottomCols: getComputedStyle(document.querySelector('.pj-grid-bottom')).gridTemplateColumns,
  });
})()
